// Created: 2026-08-04

/**
 * Unit tests for the `npm ci` vs shared-node_modules guard in
 * dangerous-command-blocker.
 *
 * Why this exists: worktree.symlinkDirectories (bin/worktree-config.sh) makes
 * every worktree's node_modules a symlink into the main repository. `npm ci`
 * clears node_modules first and FOLLOWS that symlink. Measured in a sandbox:
 * one `npm ci` emptied the shared tree and left the worktree with a local
 * directory. In this repo that is ~2 GB destroyed and 13 worktrees broken from
 * a command that prints "added 1 package" on success.
 *
 * These tests use REAL symlinks in a temp dir rather than mocking fs, because
 * the whole assertion is "does lstat see a link" and a mock would only test
 * the mock.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, mkdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput, HookContext } from '../../types.js';
import {
  dangerousCommandBlocker,
  npmCiAgainstSymlink,
} from '../../pretool/bash/dangerous-command-blocker.js';
import { NOOP_CTX } from '../../lib/context.js';

let ROOT: string;
let SHARED: string; // a "main repo" with a real node_modules
let LINKED: string; // a "worktree" whose node_modules is a symlink
let OWNED: string; // a checkout with its own real node_modules
let EMPTY: string; // a checkout with no node_modules at all

beforeAll(() => {
  ROOT = mkdtempSync(join(tmpdir(), 'npmci-guard-'));

  SHARED = join(ROOT, 'main');
  mkdirSync(join(SHARED, 'node_modules'), { recursive: true });
  writeFileSync(join(SHARED, 'node_modules', 'SENTINEL'), 'shared');

  LINKED = join(ROOT, 'worktree');
  mkdirSync(LINKED, { recursive: true });
  symlinkSync(join(SHARED, 'node_modules'), join(LINKED, 'node_modules'), 'dir');

  OWNED = join(ROOT, 'owned');
  mkdirSync(join(OWNED, 'node_modules'), { recursive: true });

  EMPTY = join(ROOT, 'empty');
  mkdirSync(EMPTY, { recursive: true });
});

afterAll(() => {
  rmSync(ROOT, { recursive: true, force: true });
});

function ctxAt(dir: string): HookContext {
  return { ...NOOP_CTX, projectDir: dir } as HookContext;
}

function bash(command: string, overrides: Partial<HookInput> = {}): HookInput {
  return {
    tool_name: 'Bash',
    session_id: 'npmci-guard-test',
    project_dir: '/test/project',
    tool_input: { command },
    ...overrides,
  };
}

describe('npmCiAgainstSymlink', () => {
  it('flags npm ci when node_modules is a symlink', () => {
    expect(npmCiAgainstSymlink('npm ci', LINKED)).toBe(join(LINKED, 'node_modules'));
  });

  it('flags npm clean-install, the long form', () => {
    expect(npmCiAgainstSymlink('npm clean-install', LINKED)).not.toBeNull();
  });

  it('flags npm ci inside a compound command', () => {
    expect(npmCiAgainstSymlink('git pull && npm ci && npm test', LINKED)).not.toBeNull();
  });

  it('resolves a `cd <worktree> && npm ci` hop from the main repo', () => {
    // Session rooted in the main repo, stepping into the linked worktree.
    // The naive check would read main/node_modules (a real dir) and pass.
    expect(npmCiAgainstSymlink(`cd ${LINKED} && npm ci`, SHARED)).toBe(
      join(LINKED, 'node_modules'),
    );
  });

  it('allows npm ci when node_modules is a real directory', () => {
    expect(npmCiAgainstSymlink('npm ci', OWNED)).toBeNull();
  });

  it('allows npm ci when node_modules does not exist', () => {
    expect(npmCiAgainstSymlink('npm ci', EMPTY)).toBeNull();
  });

  it('allows npm install against a symlink (it does not clear the tree)', () => {
    expect(npmCiAgainstSymlink('npm install', LINKED)).toBeNull();
  });

  it('does not fire on lookalike subcommands', () => {
    expect(npmCiAgainstSymlink('npm cit', LINKED)).toBeNull();
    expect(npmCiAgainstSymlink('npm ci-helper', LINKED)).toBeNull();
    expect(npmCiAgainstSymlink('echo npm', LINKED)).toBeNull();
  });

  it('returns null with no cwd rather than guessing', () => {
    expect(npmCiAgainstSymlink('npm ci', undefined)).toBeNull();
  });
});

describe('dangerous-command-blocker: npm ci guard', () => {
  it('DENIES npm ci in a worktree sharing node_modules', () => {
    const result = dangerousCommandBlocker(bash('npm ci'), ctxAt(LINKED));
    expect(result.hookSpecificOutput?.permissionDecision).toBe('deny');
    expect(result.stopReason).toContain('SHARED node_modules');
    expect(result.stopReason).toContain('npm install');
  });

  it('stays DENY under bypassPermissions', () => {
    // The check sits above the ASK gate on purpose: the damage is instant and
    // lands in worktrees the operator is not looking at.
    const bypass = { permissionMode: 'bypassPermissions' } as Partial<HookInput>;

    // Control: prove bypass is genuinely engaged for this input shape, so the
    // assertion below cannot pass just because the flag was spelled wrong.
    const askTier = dangerousCommandBlocker(bash('sudo rm -rf /tmp/x', bypass), ctxAt(OWNED));
    expect(askTier.hookSpecificOutput?.permissionDecision).not.toBe('ask');

    const result = dangerousCommandBlocker(bash('npm ci', bypass), ctxAt(LINKED));
    expect(result.hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  it('lets npm ci through in a checkout that owns its node_modules', () => {
    const result = dangerousCommandBlocker(bash('npm ci'), ctxAt(OWNED));
    expect(result.hookSpecificOutput?.permissionDecision).not.toBe('deny');
  });

  it('lets npm install through everywhere', () => {
    const result = dangerousCommandBlocker(bash('npm install'), ctxAt(LINKED));
    expect(result.hookSpecificOutput?.permissionDecision).not.toBe('deny');
  });
});
